ROOT = Path(__file__).resolve().parents[1]

def svg(title, body, height=320):
    return f'<svg viewBox="0 0 880 {height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{title}"><rect width="880" height="{height}" rx="18" fill="#f4f7f5"/><g font-family="system-ui,Microsoft YaHei,sans-serif" font-size="19" fill="#223e46">{body}</g></svg>'

def text(x, y, content, size=19, color='#223e46'):
    return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}">{content}</text>'

def box(x, y, w, h, content, fill='#e2ece9'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{fill}"/>{text(x+15,y+h/2+6,content)}'

def arrow(x, y, w):
    return f'<path d="M{x} {y}h{w}m-10 -7l10 7 -10 7" fill="none" stroke="#477f80" stroke-width="3"/>'

def pipeline(title, labels, notes):
    body = ''.join(box(25+i*173,55,155,72,t) + (arrow(184+i*173,91,13) if i<4 else '') + text(30+i*173,166,notes[i],16) for i,t in enumerate(labels))
    return svg(title,body,220)

