def manifest(scene, caseid, title, question, summary, methods, background, steps):
    return {'id':caseid,'sceneId':scene,'methods':methods,'title':title,'version':'1.0.0','updated':'2026-10-24','tabs':{
      'background':{'label':'专业背景','lede':summary,'judge':[{'label':'业务问题','value':question,'desc':'从井下结构讲到可复核判断'},{'label':'数据与方法','value':'教学合成 · 浏览器真实计算','desc':'模型、经验基线与评价真值分开'}], 'sections':[{'no':i+1,'en':'CONCEPT','title':f'图 B{i+1}｜{b["title"]}','html':f'<figure>{b["html"]}<figcaption>{b["caption"]}</figcaption></figure>'} for i,b in enumerate(background)]},
      'workflow':{'label':'案例流程','title':question,'lead':[summary],'steps':[{'name':s['name'],'role':f'图 S{i+1}','do':f'输入：{s["input"]}；动作：{s["action"]}。见图 S{i+1}。','effect':s['output'],'trap':s['trap']} for i,s in enumerate(steps)],'metrics':{'title':'逐步骤图解与评价口径','html':''.join(f'<figure><h3>图 S{i+1}｜{s["name"]}</h3>{s["figure"]}<figcaption>输入：{s["input"]}；动作：{s["action"]}；产物：{s["output"]}。{s["trap"]}</figcaption></figure>' for i,s in enumerate(steps))}},
      'demo':{'mode':'page','html':'demo/index.html','js':'demo/demo.js','label':'可运行示范','height':1250,'intro':summary}}}

CSS = r'''
:root{color-scheme:light;--ink:#203b44;--muted:#5a7178;--accent:#217f80;--paper:#fbfcfa;--line:#dce5e3;--warm:#bd884c;--bad:#a75050;--purple:#88628a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.75 system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}button{border:1px solid var(--line);border-radius:12px;background:white;color:var(--ink);padding:10px 18px;cursor:pointer;min-height:46px}button:hover:not(:disabled){border-color:var(--accent);background:#eff6f3}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid #83bcb6;outline-offset:3px}button:disabled{opacity:.45;cursor:default}button.primary{color:white;background:var(--accent);border-color:var(--accent)}header{padding:22px max(24px,calc((100vw - 1320px)/2));display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);gap:16px;background:#fff}.brand{font-size:24px;font-weight:750;letter-spacing:.05em}.brand span{font-size:16px;font-weight:500;margin-left:14px;letter-spacing:0;color:var(--muted)}.edition{color:var(--muted);font-size:15px}main{max-width:1368px;margin:auto;padding:42px 24px 70px}.kicker{text-transform:uppercase;letter-spacing:.14em;color:var(--accent);font-size:15px;font-weight:700}h1{font-size:clamp(32px,3.4vw,49px);line-height:1.35;letter-spacing:-.03em;margin:16px 0 20px;max-width:1020px}h2{font-size:28px;line-height:1.4;margin:0 0 18px}h3{font-size:21px;margin:0 0 10px}p{margin:8px 0 18px}.lead{font-size:21px;max-width:1060px;color:var(--muted)}.meta{display:flex;gap:24px;flex-wrap:wrap;color:var(--muted);font-size:16px;margin:26px 0 28px}.meta b{color:var(--ink);font-weight:600}nav[aria-label="案例内容"]{display:flex;gap:8px;border-bottom:1px solid var(--line);padding-bottom:13px;margin-bottom:32px}nav button{background:transparent;border-color:transparent;border-radius:10px;font-size:19px;padding:13px 22px}nav button[aria-pressed=true]{background:#e8f1ec;color:var(--accent);font-weight:700}.chapter{padding:36px 0 42px;border-bottom:1px solid var(--line)}.chapter:first-child{padding-top:4px}.chapter .number{font-size:15px;letter-spacing:.1em;color:var(--accent);margin-bottom:8px}.chapter figure{margin:24px 0 0}svg{display:block;width:100%;height:auto}figcaption{font-size:18px;color:var(--muted);margin-top:15px;max-width:1120px}.diagram{overflow-x:auto;border-radius:18px}.diagram>svg{min-width:720px}.sources{padding:30px 0}.sources a{color:var(--accent);word-break:break-word}.sources li{margin-bottom:10px}.steps{display:grid;grid-template-columns:260px minmax(0,1fr);gap:30px}.stepnav{display:flex;flex-direction:column;gap:8px}.stepnav button{text-align:left;border-color:transparent;border-radius:12px;padding:13px 15px;line-height:1.5}.stepnav button[aria-selected=true]{background:#e7f0eb;color:var(--accent);font-weight:700}.stepbody{padding:28px;border:1px solid var(--line);border-radius:20px;background:white;min-width:0}.step-io{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:22px 0}.step-io b{display:block;font-size:15px;color:var(--accent);margin-bottom:5px}.step-io p{font-size:18px;margin:0}.step-trap{border-left:3px solid var(--warm);padding-left:15px;color:var(--muted);margin-top:20px}.toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:14px;padding:22px 0 26px}.toolbar label{min-width:255px}.controlgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;padding:22px 0}label.control{display:flex;flex-direction:column;gap:8px;font-size:17px}label.control .label-line{display:flex;justify-content:space-between;gap:10px}output{font-variant-numeric:tabular-nums;color:var(--accent);font-weight:650}select,input[type=number],textarea{border:1px solid #c7d5d1;background:white;padding:10px 12px;border-radius:10px;color:var(--ink);min-width:0;max-width:100%;width:100%}input[type=range]{accent-color:var(--accent);width:100%;height:28px;margin:4px 0}input[type=checkbox]{width:20px;height:20px;accent-color:var(--accent);vertical-align:middle;margin-right:9px}.status{padding:12px 17px;border-radius:11px;background:#edf3ef;min-height:55px;margin-bottom:28px;color:#37635f}.status[data-state=stale]{background:#f6eddc;color:#865f2f}.status[data-state=error]{background:#f8e9e6;color:#994b42}.workspace{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(320px,1fr);gap:28px}.panel{min-width:0;background:white;border:1px solid var(--line);border-radius:20px;padding:26px;margin:0 0 26px}.panel .sub{font-size:17px;color:var(--muted);margin-top:-6px}.chart-scroll{max-width:100%;overflow-x:auto}canvas{display:block;width:100%;height:auto;max-width:100%}.plot{background:#f4f7f5;border-radius:13px;overflow:hidden}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:16px;color:var(--muted);margin-top:13px}.key{display:inline-block;width:15px;height:15px;border-radius:3px;vertical-align:-2px;margin-right:5px}.small{font-size:16px;color:var(--muted)}.selection{padding:16px 0;font-size:18px}.metrics-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;border-bottom:1px solid var(--line);padding-bottom:22px;margin-bottom:24px}.metric-label{font-size:16px;color:var(--muted)}.metric-value{font-size:32px;font-weight:730;line-height:1.5;font-variant-numeric:tabular-nums}.metric-note{font-size:15px;color:var(--muted)}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:17px}th,td{padding:11px 13px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:15px;font-weight:600;color:var(--muted);white-space:nowrap}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}.pill{font-size:15px;border-radius:20px;background:#e5f1ec;color:#246f67;padding:3px 10px;display:inline-block;white-space:nowrap}.pill.bad{background:#f5e7df;color:#9d5e37}.review{display:grid;grid-template-columns:1fr 1fr;gap:26px}.review textarea{min-height:100px;resize:vertical}.review-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:13px 0}.history{font-size:16px;color:var(--muted);max-height:180px;overflow:auto}.history p{padding:10px 0;border-bottom:1px solid var(--line)}.exportrow{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.stale-results{opacity:.45}.empty{padding:50px 20px;text-align:center;color:var(--muted);background:#f0f5f1;border-radius:14px}.choice-list{display:grid;gap:14px}.choice{padding:18px;border:1px solid var(--line);border-radius:13px}.choice.winner{border-color:var(--accent);background:#f0f7f2}.choice.excluded{background:#fbf9f4}.choice-top{display:flex;align-items:start;justify-content:space-between;gap:15px}.choice ul{padding-left:22px;margin:8px 0;font-size:16px;color:#93663f}.bar-track{height:9px;background:#e6ece7;border-radius:7px;margin-top:12px;overflow:hidden}.bar-fill{height:100%;background:var(--accent)}.condition-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.notice{padding:14px 17px;border-left:3px solid var(--warm);background:#fbf5e8;color:#79623c;font-size:17px;margin-bottom:20px}.data-notes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:25px}.data-notes p{font-size:17px;color:var(--muted)}footer{border-top:1px solid var(--line);padding:25px;max-width:1320px;margin:auto;font-size:16px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:1000px){.workspace{grid-template-columns:1fr}.controlgrid{grid-template-columns:repeat(2,minmax(0,1fr))}.steps{grid-template-columns:210px minmax(0,1fr)}.step-io{grid-template-columns:1fr}.metrics-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){body{font-size:17px}header{padding:18px 20px;align-items:start}.brand span{display:block;margin-left:0;font-size:14px}.edition{max-width:120px;text-align:right;font-size:13px}main{padding:28px 17px 50px}.lead{font-size:19px}nav[aria-label="案例内容"]{gap:3px}nav button{font-size:16px;padding:10px 11px;flex:1}.meta{gap:10px 18px}.steps{grid-template-columns:minmax(0,1fr)}.stepnav{flex-direction:row;overflow-x:auto;gap:8px}.stepnav button{min-width:160px;font-size:16px}.stepbody,.panel{padding:19px}.controlgrid{gap:15px}.condition-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.review,.data-notes{grid-template-columns:1fr}.toolbar{gap:10px}.toolbar label{min-width:100%;width:100%}.toolbar button{flex:1}.metrics-grid{gap:16px}.metric-value{font-size:29px}h2{font-size:25px}h3{font-size:20px}.choice-top{flex-wrap:wrap}.diagram>svg{min-width:700px}}
'''

COMMON = r'''
  const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = (x, n=2) => x === null || x === undefined ? '不适用' : Number(x).toFixed(n);
  const pct = x => x === null || x === undefined ? '不适用' : (100*x).toFixed(1)+'%';
  const state = {status:'idle',runId:0,result:null,reviews:[],selected:0,inputRevision:0};
  function status(s, message) {state.status=s;$('#status').dataset.state=s;$('#status').textContent=message;$('#export').disabled=s!=='ready';$('#review').disabled=s!=='ready';}
  function tabs(name) {$$('nav[aria-label="案例内容"] [data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===name)));['background','workflow','lab'].forEach(id=>$('#'+id).hidden=id!==name);}
  $$('nav[aria-label="案例内容"] [data-tab]').forEach(b=>b.onclick=()=>tabs(b.dataset.tab));tabs('background');
  $('#background-content').innerHTML=LESSON.background.map((b,i)=>`<article class="chapter"><div class="number">CONCEPT ${String(i+1).padStart(2,'0')}</div><h2>${esc(b.title)}</h2><figure><div class="diagram" tabindex="0" aria-label="概念图，可横向滚动">${b.html}</div><figcaption>${esc(b.caption)}</figcaption></figure></article>`).join('')+`<aside class="sources"><h3>专业依据与方法资料</h3><ul>${LESSON.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a></li>`).join('')}</ul><p class="small">专业概念依据以上公开资料；图形由本案例重新绘制，默认数据为固定种子的教学合成。</p></aside>`;
  let step=0;
  function showStep(n) {step=n;$('#stepnav').innerHTML=LESSON.steps.map((s,i)=>`<button role="tab" id="step-${i}" aria-controls="step-content" aria-selected="${i===n}" data-step="${i}">${String(i+1).padStart(2,'0')} · ${esc(s.name)}</button>`).join('');const s=LESSON.steps[n];$('#step-content').innerHTML=`<div class="kicker">STEP ${n+1} / ${LESSON.steps.length}</div><h2>${esc(s.name)}</h2><div class="step-io"><div><b>输入</b><p>${esc(s.input)}</p></div><div><b>动作</b><p>${esc(s.action)}</p></div><div><b>产物</b><p>${esc(s.output)}</p></div></div><div class="diagram" tabindex="0" aria-label="步骤图，可横向滚动">${s.figure}</div><p class="step-trap">${esc(s.trap)}</p><div class="review-actions"><button data-prev ${n===0?'disabled':''}>上一步</button><button data-next>${n===LESSON.steps.length-1?'开始交互实验 →':'下一步 →'}</button></div>`;$$('[data-step]').forEach(b=>b.onclick=()=>showStep(Number(b.dataset.step)));$('[data-prev]').onclick=()=>showStep(Math.max(0,step-1));$('[data-next]').onclick=()=>step===LESSON.steps.length-1?tabs('lab'):showStep(step+1);}
  $('#stepnav').onkeydown=e=>{if(!['ArrowDown','ArrowUp','ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?LESSON.steps.length-1:Math.max(0,Math.min(LESSON.steps.length-1,step+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)));showStep(n);$('#step-'+n).focus();};showStep(0);
  function renderReviewHistory(){const labels={current:'本次人工意见',history:'历史运行意见',stale:'输入已变更的历史意见'};$('#review-history').innerHTML=state.reviews.map(r=>`<p><b>${esc(r.subject)}</b> · run ${r.runId} · ${labels[r.recordStatus]}<br>${esc(r.opinion)}：${esc(r.note)}<br>当时模型：${esc(r.originalPrediction)}</p>`).join('');}
  function retireReviews(kind){state.reviews.forEach(r=>{if(r.recordStatus==='current')r.recordStatus=kind;});renderReviewHistory();}
  function stale() {state.inputRevision++;retireReviews('stale');if(state.status==='idle')return;status('stale','实验条件已变化 · 请重新计算当前结果；先前人工意见保留在历史中');$('#results').classList.add('stale-results');}
  function metric(label,value,note) {return `<div><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
  function chart(id,width,height) {const c=$('#'+id);c.width=width*2;c.height=height*2;const q=c.getContext('2d');q.scale(2,2);q.fillStyle='#f4f7f5';q.fillRect(0,0,width,height);q.font='16px system-ui,"Microsoft YaHei"';q.textBaseline='middle';q.lineJoin='round';return q;}
  function label(q,x,y,t,color='#546d75',align='left'){q.fillStyle=color;q.textAlign=align;q.fillText(t,x,y);q.textAlign='left';}
  function download() {if(state.status!=='ready')return;const evidence=exportEvidence();const blob=new Blob([JSON.stringify(evidence,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=CASE_ID+'-run-'+state.runId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  $('#export').onclick=download;
  $('#review').onclick=()=>{if(state.status!=='ready')return;const note=$('#review-note').value.trim();if(!note){$('#review-note').setCustomValidity('请填写当前观察与复核依据');$('#review-note').reportValidity();return;}$('#review-note').setCustomValidity('');const review={runId:state.runId,inputRevision:state.inputRevision,recordStatus:'current',recordedAt:new Date().toISOString(),subject:selectedId(),opinion:$('#review-choice').value,note,originalPrediction:selectedPrediction(),sourceSnapshot:reviewObservation()};state.reviews.push(review);renderReviewHistory();};
  $('#review-note').oninput=()=>$('#review-note').setCustomValidity('');
  g.CaseInspect={snapshot:()=>({sceneId:SCENE_ID,caseId:CASE_ID,status:state.status,runId:state.runId,params:readParams(),metrics:state.status==='ready'?state.result.metrics:null,reviewCount:state.reviews.length,currentReviewCount:state.reviews.filter(r=>r.recordStatus==='current'&&r.runId===state.runId).length})};
'''

c1sources=[{'title':'SLB Oilfield Glossary · cement bond log','url':'https://glossary.slb.com/en/terms/c/cement_bond_log'}, {'title':'SLB Oilfield Glossary · variable-density log','url':'https://glossary.slb.com/en/terms/v/variable-density_log'},{'title':'SLB · Cement bond logging tools','url':'https://www.slb.com/products-and-services/innovating-in-oil-and-gas/well-construction/well-cementing/cement-evaluation/cement-bond-logging-tools'},{'title':'scikit-learn · Nearest Neighbors 方法原理','url':'https://scikit-learn.org/stable/modules/neighbors.html'}]
co1sources=[{'title':'SLB Oilfield Glossary · openhole completion','url':'https://glossary.slb.com/en/terms/o/openhole_completion'},{'title':'SLB Oilfield Glossary · casing completion','url':'https://glossary.slb.com/Terms/c/casing_completion.aspx'},{'title':'SLB Oilfield Glossary · sand control','url':'https://glossary.slb.com/terms/s/sand_control'},{'title':'SLB · Introduction to Well Completions','url':'https://www.slb.com/resource-library/oilfield-review/defining-series/defining-completion'},{'title':'scikit-learn · Nearest Neighbors Regression 方法原理','url':'https://scikit-learn.org/stable/modules/neighbors.html#nearest-neighbors-regression'}]

def html(title,question,summary,scene,lab):
    method = '声学波形特征 + kNN' if scene == 'c1' else '近邻响应回归 + 约束排序'
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>井见 · {title}</title><link rel="stylesheet" href="demo.css"></head><body><header><div class="brand">井见 <span>石油智能化可视实验室</span></div><div class="edition">{scene.upper()} · 扩展案例<br>教学合成 · 离线运行</div></header><main><div class="kicker">Petroleum × Intelligence</div><h1>{question}</h1><p class="lead">{summary}</p><div class="meta"><span><b>专业对象</b> {title}</span><span><b>方法</b> {method}</span><span><b>操作</b> 修改 · 重算 · 对比 · 复核</span></div><nav aria-label="案例内容"><button data-tab="background">专业背景</button><button data-tab="workflow">案例流程</button><button data-tab="lab">可运行示范</button></nav><section id="background"><div id="background-content"></div></section><section id="workflow" hidden><div class="steps"><div id="stepnav" class="stepnav" role="tablist" aria-label="案例流程步骤"></div><article id="step-content" class="stepbody" role="tabpanel" aria-live="polite"></article></div></section><section id="lab" hidden>{lab}</section></main><footer>井见 · 学号 17 扩展案例 · {scene} · v1.0.0 · 默认数据为固定种子的教学合成</footer><script src="demo.js"></script></body></html>'''

def review_html(choices):
    return f'''<article class="panel"><h2>把需要复核的判断留下来</h2><p class="sub">人工意见与模型原始结果分别记录，评价成绩保持原始预测口径。</p><div class="review"><label class="control">当前选择<select id="review-choice">{''.join(f'<option>{v}</option>' for v in choices)}</select></label><label class="control">观察与依据<textarea id="review-note" rows="3" maxlength="600" placeholder="说明你参考了哪些曲线、条件或近邻证据"></textarea></label></div><div class="review-actions"><button id="review" disabled>保存当前人工意见</button></div><div id="review-history" class="history" aria-live="polite"></div></article><article class="panel exportrow"><div><h2>保存这次比较</h2><p class="small">结果包包含参数、数据版本、原始预测、指标分母、近邻证据与人工意见。</p></div><button id="export" disabled>下载当前证据 JSON</button></article>'''

c1lab='''<div class="toolbar"><label class="control">教学情景<select id="preset"><option value="default">常规测量 · 四口留出井</option><option value="micro">微环空 · 早到声幅升高</option><option value="eccentric">偏心干扰 · 沿深度起伏</option><option value="noise">高噪声 · 证据变弱</option><option value="reject">严格复核 · 提高拒判门槛</option></select></label><button id="run" class="primary">运行计算</button><button id="reset">恢复默认</button></div><div class="controlgrid"><label class="control"><span class="label-line">声幅噪声 <output id="noise-out">0.035</output></span><input id="noise" type="range" min="0" max="0.30" step="0.005" value="0.035"></label><label class="control"><span class="label-line">偏心扰动 <output id="eccentric-out">0.00</output></span><input id="eccentric" type="range" min="0" max="2" step="0.05" value="0"></label><label class="control"><span class="label-line">微环空扰动 <output id="micro-out">0.00</output></span><input id="micro" type="range" min="0" max="1.5" step="0.05" value="0"></label><label class="control"><span class="label-line">投票支持度门槛 <output id="reject-out">0.60</output></span><input id="reject" type="range" min="0.35" max="1" step="0.01" value="0.60"></label></div><details><summary>展开声幅基线阈值实验</summary><label class="control"><span class="label-line">相对验证阈值平移 <output id="thresholdShift-out">0.00</output></span><input id="thresholdShift" type="range" min="-0.15" max="0.15" step="0.01" value="0"></label><p class="small">默认基线阈值与 k 均只在验证井选定。此处平移属于测试集教学探索。</p></details><div id="status" class="status" role="status" aria-live="polite">先选择“运行计算”，生成当前声学观测、模型预测与对照。</div><div id="results"><div class="workspace"><article class="panel"><h2>同一深度，联动查看三条证据</h2><p class="sub">左：早到声幅；中：VDL 波列；右：模型与阈值分类。点击深度定位。</p><div class="controlgrid" style="grid-template-columns:1fr 1.4fr"><label class="control">测试井<select id="well"><option value="0">TE-01</option><option value="1">TE-02</option><option value="2">TE-03</option><option value="3">TE-04</option></select></label><label class="control">选中深度 / m MD<input id="depth" type="range" min="0" max="47" step="1" value="16"></label></div><div class="plot"><canvas id="logs" aria-label="声幅、波列与分类按深度联动图"></canvas></div><div class="legend"><span><i class="key" style="background:#367f79"></i>较好响应</span><span><i class="key" style="background:#bc985c"></i>过渡响应</span><span><i class="key" style="background:#a76058"></i>弱胶结响应</span><span><i class="key" style="background:#adb7b9"></i>待复核</span></div><label><input id="show-truth" type="checkbox">在深度图中揭示独立教学真值</label><p id="selected-info" class="selection">运行后可选择深度。</p></article><article class="panel"><h2>声波从哪里提供了额外信息？</h2><div class="plot"><canvas id="wave" aria-label="选中深度的早到与后到声波"></canvas></div><div id="feature-table"></div><h3 style="margin-top:24px">实际训练近邻</h3><p class="small">下图展示早到/后到 RMS 两维；投票距离使用全部四维。</p><div class="plot"><canvas id="scatter" aria-label="训练特征与当前近邻"></canvas></div><div id="neighbors" class="table-scroll"></div></article></div><article class="panel"><h2>同一批留出井上的实际对照</h2><p class="sub">4 口独立井 × 48 个深度点 = 192 点；拒判留在评价分母里。</p><div id="metrics"><div class="empty">运行后计算宏 F1、覆盖率与错误位置。</div></div></article></div>'''+review_html(['待补充声学资料','保留模型候选','倾向较好胶结响应','倾向部分胶结响应','倾向弱胶结响应'])+'''<article class="panel"><h2>数据站：观测、模型和评价分别来自哪里</h2><div class="data-notes"><div><h3>观测</h3><p>80 点合成声波；早到套管波与后到地层波分别生成。井间具有仪器增益和地层响应差异。</p></div><div><h3>学习</h3><p>18口训练井拟合标准化，6口验证井选择 k 与声幅分档阈值；全程不使用测试井真值。</p></div><div><h3>解释范围</h3><p>三类响应是教学胶结等级。微环空、偏心和高噪声可增加误判；可通过情景预设逐项观察。</p></div></div><div id="learning-summary" class="small"></div></article>'''

co1lab='''<div class="toolbar"><label class="control">教学情景<select id="preset"><option value="default">常规井况 · 完整预算</option><option value="conflict">出砂 + 控水双重需求</option><option value="budget">预算不足 · 没有可行方案</option><option value="hot">高温井 · 筛管条件不满足</option><option value="custom">自定义井况</option></select></label><button id="run" class="primary">运行计算</button><button id="reset">恢复默认</button></div><div class="controlgrid" style="grid-template-columns:1.2fr 1fr 1fr"><label class="control">当前井<select id="well"></select></label><label class="control"><span class="label-line">预算 / 费用指数 <output id="budget-out">90</output></span><input id="budget" type="range" min="15" max="100" step="1" value="90"></label><label class="control"><span class="label-line">费用偏好系数 <output id="costWeight-out">0.22</output></span><input id="costWeight" type="range" min="0" max="0.65" step="0.01" value="0.22"></label></div><details open><summary>当前井的可见输入 · 修改后成为自定义井</summary><div class="condition-grid"><label class="control"><span class="label-line">岩石强度指数 <output id="strength-out"></output></span><input id="strength" type="range" min="0.05" max="1" step="0.01"></label><label class="control"><span class="label-line">出砂风险指数 <output id="sand-out"></output></span><input id="sand" type="range" min="0" max="1" step="0.01"></label><label class="control"><span class="label-line">非均质指数 <output id="hetero-out"></output></span><input id="hetero" type="range" min="0" max="1" step="0.01"></label><label class="control"><span class="label-line">分层控水需求 <output id="water-out"></output></span><input id="water" type="range" min="0" max="1" step="0.01"></label><label class="control"><span class="label-line">渗透率 / mD <output id="logK-out"></output></span><input id="logK" type="range" min="1.2" max="3.3" step="0.01"></label><label class="control"><span class="label-line">温度 / °C <output id="temperature-out"></output></span><input id="temperature" type="range" min="60" max="205" step="1"></label></div></details><div id="query-note" class="notice"></div><div id="status" class="status" role="status" aria-live="polite">运行后，从历史井学习响应、筛除不满足条件的候选并比较。</div><div id="results"><div class="workspace"><article class="panel"><h2>条件改变时，哪些方案还能留下？</h2><p class="sub">响应由学习器估计；每条排除原因来自公开教学约束。</p><div class="plot"><canvas id="comparison" aria-label="四方案响应、费用罚项和效用对照"></canvas></div><div class="legend"><span>━ 预测响应</span><span>■ 扣除费用后的效用</span><span>╳ 条件不满足</span></div><div id="recommendation" class="selection"></div><div id="candidate-list" class="choice-list"></div></article><article class="panel"><h2>推荐依据来自哪些历史井？</h2><p class="small">坐标是出砂风险与控水需求，完整距离采用六维标准化输入。</p><div class="plot"><canvas id="neighbors-plot" aria-label="训练历史井与查询井的条件分布"></canvas></div><div id="neighbor-table" class="table-scroll"></div><h3 style="margin-top:25px">经验规则的同台对照</h3><p class="small">出砂 &gt; 0.55 → 筛管；否则控水 &gt; 0.60 → 射孔；否则裸眼。选定后接受相同可行性检查。</p><div id="baseline-note"></div></article></div><article class="panel"><h2>留出井评价：收益与覆盖一起看</h2><p class="sub">32 口独立井；每井 4 个方案，共 128 个响应评分。自定义井单独推理，评价仍使用固定留出井。</p><div id="metrics"><div class="empty">运行后计算代理误差、推荐覆盖与机会损失。</div></div></article></div>'''+review_html(['补充资料后再选择','保留模型排序','优先考虑裸眼','优先考虑套管射孔','优先考虑裸眼筛管防砂','优先考虑射孔+砾石充填'])+'''<article class="panel"><h2>数据站：学习的到底是什么？</h2><div class="data-notes"><div><h3>合成历史试验库</h3><p>160训练井、40验证井、32测试井；每井按四个固定方案生成响应，包含进流、出砂、控水与温度影响。</p></div><div><h3>学习与规则分工</h3><p>kNN 回归学习六维条件到四方案综合响应；预算、井壁支撑、防砂、隔离与设备温度规则显式执行。</p></div><div><h3>分数与单位</h3><p>综合表现和费用是本例教学指数。效用只在当前四个候选之间比较；温度单位 °C，渗透率单位 mD。</p></div></div><div id="learning-summary" class="small"></div></article>'''

config = [
 ('c1','s17x-c1-cement-quality','固井质量智能评价','沿着井深，把声学响应变成可以复核的胶结判断','观察套管波幅与后到波列，比较单声幅阈值和多特征近邻；亲手加入微环空、偏心或噪声，查看哪些深度需要补充证据。',['ts'],c1bg,c1steps,c1sources,c1lab),
 ('co1','s17x-co1-completion-choice','完井方式智能优选','一口井的多种需求，怎样共同决定完井候选？','从裸眼、套管射孔与防砂结构出发，用历史井近邻估计响应，再让预算、井壁支撑、防砂、控水与温度条件共同筛选候选。',['kg','opt'],co1bg,co1steps,co1sources,co1lab)
]
